const r = await tools.exec_command({"cmd":"$ErrorActionPreference='Stop'
$stackmapDockerConfig = Join-Path ([System.IO.Path]::GetTempPath()) ('stackmap-docker-' + [guid]::NewGuid().ToString('N'))
$stackmapConfigDir = Join-Path ([System.IO.Path]::GetTempPath()) ('stackmap-config-' + [guid]::NewGuid().ToString('N'))
$stackmapContainer = 'stackmap-published-' + [guid]::NewGuid().ToString('N').Substring(0,12)
New-Item -ItemType Directory -Path $stackmapDockerConfig,$stackmapConfigDir | Out-Null
try {
  $env:DOCKER_CONFIG = $stackmapDockerConfig
  docker pull --platform linux/amd64 ghcr.io/five2seven/stackmap:latest
  $imageInspect = docker image inspect ghcr.io/five2seven/stackmap:latest | ConvertFrom-Json
  docker run --detach --name $stackmapContainer --read-only --tmpfs /tmp --cap-drop ALL --security-opt no-new-privileges:true --mount "type=bind,source=$stackmapConfigDir,target=/config" --publish 127.0.0.1::8080 ghcr.io/five2seven/stackmap:latest | Out-Null
  $binding = docker port $stackmapContainer 8080/tcp
  $port = ($binding -split ':')[-1]
  $healthy = $false
  foreach ($attempt in 1..30) {
    $health = docker inspect --format='{{if .State.Health}}{{.State.Health.Status}}{{else}}none{{end}}' $stackmapContainer
    if ($health -eq 'healthy') { $healthy = $true; break }
    if ($health -eq 'unhealthy') { break }
    Start-Sleep -Seconds 2
  }
  if (-not $healthy) { throw "Published container did not become healthy: $health" }
  $meta = Invoke-RestMethod "http://127.0.0.1:$port/api/v1/meta"
  [pscustomobject]@{
    AnonymousPull = 'succeeded'
    RepoDigest = $imageInspect.RepoDigests
    Architecture = $imageInspect.Architecture
    Os = $imageInspect.Os
    ConfigUser = $imageInspect.Config.User
    ContainerHealth = $health
    DatastoreAuthority = $meta.datastoreAuthority
    SchemaVersion = $meta.schemaVersion
  } | ConvertTo-Json -Depth 4
}
finally {
  docker rm --force $stackmapContainer 2>$null | Out-Null
  Remove-Item -LiteralPath $stackmapDockerConfig -Recurse -Force -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath $stackmapConfigDir -Recurse -Force -ErrorAction SilentlyContinue
  Remove-Item Env:DOCKER_CONFIG -ErrorAction SilentlyContinue
}","workdir":"C:\Code\Projects\APP-StackMap","yield_time_ms":30000,"max_output_tokens":12000});
